import {sql} from 'drizzle-orm';
import {sqliteTable, text, integer, index, primaryKey, check} from 'drizzle-orm/sqlite-core';

// Keep migrations generated by Drizzle in the hosting project. The Worker only
// runs prepared statements and never creates or mutates the database schema.
export const toonUsers = sqliteTable('toon_users', {
  id: text('id').primaryKey(),
  username: text('username').notNull().unique(),
  passwordSalt: text('password_salt').notNull(),
  passwordHash: text('password_hash').notNull(),
  passwordIterations: integer('password_iterations').notNull(),
  recoveryHash: text('recovery_hash').notNull(),
  createdAt: integer('created_at').notNull(),
}, table => [check('toon_users_password_iterations_check', sql`${table.passwordIterations} >= 100000`)]);

export const toonSessions = sqliteTable('toon_sessions', {
  tokenHash: text('token_hash').primaryKey(),
  userId: text('user_id').notNull().references(() => toonUsers.id, {onDelete: 'cascade'}),
  createdAt: integer('created_at').notNull(),
  expiresAt: integer('expires_at').notNull(),
}, table => [index('toon_sessions_user').on(table.userId, table.createdAt), index('toon_sessions_expiry').on(table.expiresAt)]);

export const toonSaves = sqliteTable('toon_saves', {
  userId: text('user_id').primaryKey().references(() => toonUsers.id, {onDelete: 'cascade'}),
  revision: integer('revision').notNull().default(0),
  bundle: text('bundle').notNull(),
  updatedAt: integer('updated_at'),
}, table => [check('toon_saves_revision_check', sql`${table.revision} >= 0`)]);

export const toonSaveSnapshots = sqliteTable('toon_save_snapshots', {
  userId: text('user_id').notNull().references(() => toonUsers.id, {onDelete: 'cascade'}),
  revision: integer('revision').notNull(),
  bundle: text('bundle').notNull(),
  updatedAt: integer('updated_at').notNull(),
}, table => [primaryKey({columns: [table.userId, table.revision]}), check('toon_save_snapshots_revision_check', sql`${table.revision} > 0`)]);

export const toonRateLimits = sqliteTable('toon_rate_limits', {
  bucket: text('bucket').primaryKey(),
  count: integer('count').notNull(),
  expiresAt: integer('expires_at').notNull(),
}, table => [index('toon_rate_limits_expiry').on(table.expiresAt), check('toon_rate_limits_count_check', sql`${table.count} > 0`)]);
